You can sort a string s in o(|s|) time and o(1) time complexity, so I went with first solution:
def groupAnagrams(self, strs):
        """
        :type strs: List[str]
        :rtype: List[List[str]]
        """
        classDict = {}
        
        for string in strs:
            #cannoinze
            letters = list(string)
            letters.sort()
            key = join(letters,",")

            
            if key not in classDict:
                classDict[key] = []
            classDict[key].append(string)           
        return list(classDict.values())

