got = -1


def search(nums, n):
    l = 0
    u = len(nums) - 1
    for x in range(len(nums)):
        mid = (l + u) // 2
        if nums[mid] == n:
            globals()['got'] = mid+1
            return True
        else:
            if nums[mid] < n:
                l = mid + 1
            else:
                u = mid - 1
    return False


