Niiiice, It took me like an hour but I solved this problem and used almost exactly the same method as you. My code was obviously not as pretty but it largely used the same ideas. I had a similar idea with the boxes but I didn't come up with the (c/3, r/3) idea, I just numbered them 0-8 using a function which made mine a lot slower.

class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        hashmap = {}
        for num in range(1, 10):
            hashmap[num] = {
                'x': set(),
                'y': set(),
                'box': set()
            } 

        for row, _ in enumerate(board):
            for col, n in enumerate(board[row]):
                if n == '.':
                    continue

                box = self.whichBox(col, row)
                n = int(n)
                if col in hashmap[n]['x'] or row in hashmap[n]['y'] or box in hashmap[n]['box']:
                    return False

                hashmap[n]['x'].add(col)
                hashmap[n]['y'].add(row)
                hashmap[n]['box'].add(box)

        return True

    def whichBox(self, col, row):
        box = 0

        if 3 <= row <= 5:
            box += 3
        elif row > 5:
            box += 6

        if 3 <= col <= 5:
            box += 1
        elif col > 5:
            box += 2

        return box

