*class Solution:
    def numDecodings(self, s: str) -> int:

        memo={len(s):1}
        
        def recur(i):
            if(i in memo):
                return memo[i]
            
            count=0
            for j in range(i,min(i+2,len(s))):
                num=int(s[i:j+1])
                if(num<=26 and num>=1 and str(num)==s[i:j+1]):
                    count+=recur(j+1)
            memo[i]=count
            return(memo[i])
        
        return(recur(0))*

