var trap = function(height) {
    let collected = 0
    let [l,r,lMax, rMax] = [0, height.length, 0, 0]

    while(l < r){
        (height[l] < lMax) ? collected+=lMax-height[l] : lMax=height[l];
        (height[r] < rMax) ? collected+=rMax-height[r] : rMax=height[r];
        (height[l] <= height[r]) ? l++ : r--;
    }
    return collected
};

