Overcomplicated. My O(n) time solution:

from collections import Counter


class Solution:
    def checkInclusion(self, substr: str, parent: str) -> bool:
        n, w = len(parent), len(substr)
        if w > n:
            return False
        want = Counter(substr)

        # Load the first window.
        for l in range(w):
            ch = parent[l]
            want[ch] -= 1
            if not want[ch]:
                del want[ch]

        for l in range(n - w + 1):
            if not want:
                return True
            # Remove the leftmost element and add the right
            if l + w < n:
                r_char = parent[l + w]
                want[r_char] -= 1
                if not want[r_char]:
                    del want[r_char]
            l_char = parent[l]
            want[l_char] += 1
            if not want[l_char]:
                del want[l_char]
        return False

