import java.util.Scanner;

public class LastDigitCheck {
    public static boolean lastDigit(int a, int b) {
        return (a % 10) == (b % 10);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter two non-negative integers:");
        int num1 = scanner.nextInt();
        int num2 = scanner.nextInt();

        if (lastDigit(num1, num2)) {
            System.out.println("True: They have the same last digit.");
        } else {
            System.out.println("False: They do not have the same last digit.");
        }
        scanner.close();
    }
}

