For anyone stump on the test cases [805306368,805306368,805306368] h = 1000000000, using C++, the root cause is int will overflow. Please refer to the solution below: 

 int minEatingSpeed(vector<int>& piles, int h) {
        sort(piles.begin(), piles.end());
        int lower = 1;
        int upper = piles.back();
        int res = upper;
        while (lower <= upper) {
            int mid = lower + (upper - lower) / 2;
            std::cout << etaCost(piles, mid) << "\n"; // 
            unsigned int cost = etaCost(piles, mid); // this is the key, if use int cost, it will overflow and yield the wrong result.

            if (cost > h) {
                lower = mid + 1;
            }  else {
                res = min(res, mid);
                upper = mid - 1;
            }
        }

        return res;
    }

     unsigned int etaCost(vector<int>& piles, int speed) {        
        unsigned int time = 0;
        for (int i = 0; i < piles.size(); i++) {
            time += piles[i] / speed + (piles[i] % speed > 0 ? 1: 0);  // same here, we should use unsigned int vs int, otherwise it will overflow.
        }

        return time;
    }

