def groupAnag(list):
    result = {}
    for item in list:
        itemResult = []
        for letter in item:
            itemResult.append(letter)
        itemResult.sort()
        itemResult = ''.join(itemResult)
        if itemResult in result:
            result[itemResult].append(item)
        else:
            result[itemResult] = [item]
    my_list = [i for i in result.values()]
    return my_list

def numDecodings(self, s: str) -> int:
        if s[0] == '0':
            return 0
        
        n = len(s)
        dp = [0] * (n + 1)
        dp[0], dp[1] = 1, 1

        for i in range(2, n + 1):
            one = int(s[i - 1])
            two = int(s[i - 2:i])

            if 1 <= one <= 9:
                dp[i] += dp[i - 1]
            if 10 <= two <= 26:
                dp[i] += dp[i - 2]

        return dp[n]


