class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        hashMap = {}

        for word in strs:
            key = str(sorted(word))
            if key not in hashMap.keys():
                hashMap[key] = [word]
            else: hashMap[key] += [word]
        return list(hashMap.values())

